from pathlib import Path
from PIL import Image
import json,hashlib
p=Path(__file__).resolve().parent;r=p.parents[1];out=p/'donor-bridge-v19';out.mkdir(exist_ok=True)
inventoryfile=r/'character/james-full-set-review-2026-10-02/source-inventory.json';inventory=json.loads(inventoryfile.read_bytes())
refs=[r/'character/james-carry-headcaps-v1/frames/004.png',p/'master-head-review-v16/bare-000.png',r/'character/james-west-master-carry-v1/local-original.png']
crop=[64,96,208,240];rect=[88,104,166,228];head=[102,62,155,110]
for slot,donor_slot in [(1,2),(2,1)]:
 name=f'start-{slot:03}';donor=r/inventory['states']['bare']['carry-settle-west']['frameFiles'][donor_slot]
 base=Image.open(donor).convert('RGBA');assert base.size==(256,256);base.paste(Image.open(refs[0]).convert('RGBA').crop(head),head[:2]);basefile=out/f'{name}-base.png';base.save(basefile)
 files=[donor,basefile,inventoryfile,Path(__file__),p/'package_donor_bridge_v19.py']+refs;targets=[]
 for f,label in [(basefile,'target')]+list(zip(refs,['standing-reference','walk-reference','body-master'])):
  target=out/f'{name}-{label}.png';Image.open(f).convert('RGBA').crop(crop).resize((576,576),Image.Resampling.LANCZOS).save(target);files.append(target);targets.append(target)
 prompt=f'''Edit image1 ONLY: James carrying stance interior{slot}, based on an ACTUAL existing authored settling pose. Image1 owns the pose: preserve its specific hip/thigh/kneepad/shin/boot placement, small torso yaw and planted foot contacts. Do NOT drift toward either endpoint or invent a fraction of a turn. Image2 is standing-carry master reference; image3 is current walk-ready master reference; image4 is original selected standing costume/material. Same144x144 native crop enlarged4x, fixed full256 canvas, pivot128224,H148. Repair image1 suit/anatomical detail/material and carried case to match images2/3/4, retaining its actual intermediate leg stance. Correct old soft generic knee/boot surfaces toward the masters' recognizable panels, straps and boot design WITHOUT enlarging pads/boots or sliding soles. Ground stays nativey224/cropy128, torso and body ruler remain fixed. Case must be the SAME modest graphite rectangular case as images2/3: same physical panel dimensions and modest depth, four SMALL dull silver corner latches, coherent far glove LEFT-edge grip and near glove RIGHT-edge grip, at matching low waist height. Old image1 case is larger and darker; rebuild case/connected grip to the physical master proportions without moving the body. Keep soft detailed neutral MATTE grey/yellow sprite material, no gloss, purple cast, bright outline or chunky graphic simplification. The exact selected standing head/collar is already installed in image1: preserve it and its framing. Anatomical-left belt meter matches the reference's high attachment and is naturally masked by the carrying glove; remove any old near-side silver wrench/ring loop and do not duplicate or relocate the meter. Anatomical-right wrench is far-side occluded in this view. No black holes, fused/crossed legs, detached hand, case clipping through stomach, kicked-forward foot or per-pose height fitting. Return the SAME full square image1 crop with transparent background. Make a master-consistent version of this exact intermediate pose, not another endpoint pose.'''
 pf=out/f'{name}-prompt.txt';pf.write_text(prompt+'\n',encoding='utf-8');files.append(pf)
 (out/f'{name}-inputs.json').write_text(json.dumps({'preCallSha256':{f.relative_to(r).as_posix():hashlib.sha256(f.read_bytes()).hexdigest() for f in set(files)},'crop':crop,'admissionRegion':rect,'headRegion':head,'baseFile':basefile.relative_to(r).as_posix(),'headSource':refs[0].relative_to(r).as_posix(),'donorSource':donor.relative_to(r).as_posix(),'donorSlot':donor_slot,'references':[f.relative_to(r).as_posix() for f in targets],'scope':'Actual authored old-settle pose guides; master detail/case/material repair without guessed stance fractions or per-pose fitting.'},indent=2)+'\n')
print('Two actual settled-motion pose donors frozen with master repair references.')
